const fs = require('fs');
const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
let count1 = 0, count2 = 0;
for (let i = 1; i <= n; i++) {
  if (input[i] === 1) count1++;
  else count2++;
}
const p = input[n + 1];
const m = input[n + 2];

console.log(count1 <= p && count2 <= m ? 'S' : 'N');
